import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Supervillain Rumble","description":"","frontmatter":{},"headers":[],"relativePath":"formats/archenemy/variants/rumble.md","filePath":"formats/archenemy/variants/rumble.md","lastUpdated":null}'),o={name:"formats/archenemy/variants/rumble.md"};function i(s,e,l,h,c,m){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="supervillain-rumble" tabindex="-1">Supervillain Rumble <a class="header-anchor" href="#supervillain-rumble" aria-label="Permalink to &quot;Supervillain Rumble&quot;">​</a></h1><p><a href="./../">Archenemy versions</a> · <strong>Rules: constructed free-for-all</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>This is the free-for-all version of Archenemy, normally for three or more players. Every player is an archenemy and supplies:</p><ul><li>An ordinary constructed deck of at least 60 cards, following the agreed card pool and normal copy limits.</li><li>A separate scheme deck of at least 20 cards, with no more than two cards of any one English name.</li><li>Required tokens, counters, and life-tracking aids.</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Shuffle each ordinary deck and scheme deck separately.</li><li>Keep each scheme deck face down in its owner&#39;s command zone.</li><li>Every player starts at <strong>40 life</strong>.</li><li>Randomly determine the starting player.</li><li>Draw seven cards each and take normal multiplayer mulligans.</li></ol><h2 id="turns-and-combat" tabindex="-1">Turns and combat <a class="header-anchor" href="#turns-and-combat" aria-label="Permalink to &quot;Turns and combat&quot;">​</a></h2><p>Take individual turns in ordinary turn order. There is no hero team, shared team turn, or shared life total. The starting player draws on their first turn.</p><p>Each player sets a scheme in motion at the beginning of their own precombat main phase. In the procedure below, “the archenemy” means the player whose turn it is.</p><p>Players may attack multiple opponents in the same combat, choosing the defending player or other legal attack destination for each creature. You cannot block for another opponent. Apply ordinary free-for-all rules.</p><h2 id="setting-schemes-in-motion" tabindex="-1">Setting schemes in motion <a class="header-anchor" href="#setting-schemes-in-motion" aria-label="Permalink to &quot;Setting schemes in motion&quot;">​</a></h2><p>Keep the scheme deck shuffled, face down in the command zone, separate from the ordinary library. Its owner cannot inspect or rearrange it without an effect allowing that.</p><p>As the archenemy&#39;s precombat main phase begins on each of their turns, turn the top scheme face up in the command zone. This mandatory turn-based action sets the scheme in motion and does not use the stack. Abilities that trigger from it do use the stack, so players can respond to those abilities.</p><p>Choose targets when putting a triggered ability on the stack. Make choices or payments that the effect asks for during resolution at that time, rather than while revealing the scheme.</p><p>Schemes stay in the command zone. They are not battlefield permanents, cannot be cast, and cannot be destroyed with an effect that destroys a permanent. A face-up scheme&#39;s abilities function from the command zone.</p><h3 id="non-ongoing-schemes" tabindex="-1">Non-ongoing schemes <a class="header-anchor" href="#non-ongoing-schemes" aria-label="Permalink to &quot;Non-ongoing schemes&quot;">​</a></h3><p>A face-up, non-ongoing scheme goes face down on the bottom of its owner&#39;s scheme deck as a state-based action once no scheme triggered abilities are on the stack or waiting to be put there. Countering its ability does not leave the scheme permanently face up.</p><h3 id="ongoing-schemes" tabindex="-1">Ongoing schemes <a class="header-anchor" href="#ongoing-schemes" aria-label="Permalink to &quot;Ongoing schemes&quot;">​</a></h3><p>An ongoing scheme stays face up until an ability tells its controller to abandon it. Abandoning it turns it face down and puts it on the bottom of its owner&#39;s scheme deck. Its printed condition determines when that happens; revealing another scheme does not automatically abandon it.</p><p>Follow individual scheme instructions for additional schemes, costs, choices, and exceptions. A scheme asking an opponent to choose “self” or “others” still permits “others” when that opponent has no teammates, even if that option affects nobody.</p><h2 id="winning-losing-and-leaving" tabindex="-1">Winning, losing, and leaving <a class="header-anchor" href="#winning-losing-and-leaving" aria-label="Permalink to &quot;Winning, losing, and leaving&quot;">​</a></h2><p>Win by being the last remaining player or through a normal winning effect. Ordinary Magic loss conditions apply, including zero life, ten poison counters, and drawing from an empty library.</p><p>When a player leaves, their owned cards, including their schemes, leave the game; apply the rest of the multiplayer leaving rules. The surviving players continue. Simultaneous loss of all remaining players results in a draw.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="https://magic.wizards.com/en/formats/archenemy" target="_blank" rel="noreferrer">Wizards&#39; Supervillain Rumble rules</a> and <a href="https://magic.wizards.com/en/rules" target="_blank" rel="noreferrer">Comprehensive Rules</a> 904.12.</p><p>For Commander decks and singleton scheme decks, use <a href="./rumble-commander.html">Commander Supervillain Rumble</a>.</p>',27)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
